#include <windows.h>
#include <cstdio>
#include <vector>
#include "MVDCore.h"
#include "CalibBoardCalibCpp.h"
using namespace VisionDesigner;using namespace VisionDesigner::CalibBoardCalib;
int main(int argc,char**argv){if(argc!=2)return 2;SetErrorMode(SEM_FAILCRITICALERRORS|SEM_NOGPFAULTERRORBOX);SetDllDirectoryA(argv[1]);auto sdk=LoadLibraryA("MVDCalibBoardCalibCpp.dll"),images=LoadLibraryA("MVDImageCpp.dll");auto create=(int(*)(ICalibBoardCalibTool**))GetProcAddress(sdk,"CreateCalibBoardCalibToolInstance");auto destroy=(int(*)(ICalibBoardCalibTool*))GetProcAddress(sdk,"DestroyCalibBoardCalibToolInstance");auto createImage=(int(*)(IMvdImage**))GetProcAddress(images,"CreateImageInstance");auto destroyImage=(int(*)(IMvdImage*))GetProcAddress(images,"DestroyImageInstance");ICalibBoardCalibTool*tool=nullptr;if(create(&tool))return 3;tool->GetBasicParam()->SetCalibBoardType((MVD_CALIBBOARD_TYPE)2);tool->SetRunParam("HomoFreedom","1");tool->SetRunParam("CalibBoardWeightFun","2");int index=0;
 for(int mode:{1,2})for(int contrast:{2,5,255})for(int high:{1,40}){IMvdImage*image=nullptr;createImage(&image);image->InitImage(480,400,MVD_PIXEL_MONO_08);auto p=image->GetImageData(0)->pData;memset(p,mode==1?255:0,480*400);for(int y=0;y<8;y++)for(int x=0;x<10;x++)for(int dy=-9;dy<=9;dy++)for(int dx=-9;dx<=9;dx++)if(dx*dx+dy*dy<81)p[(80+30*y+dy)*480+90+30*x+dx]=mode==1?255-contrast:contrast;tool->SetInputImage(image);char value[32];sprintf_s(value,"%d",mode);tool->SetRunParam("CircleBoardCircleMode",value);sprintf_s(value,"%d",high==1?1:20);tool->SetRunParam("EdgeThreshLow",value);sprintf_s(value,"%d",high);tool->SetRunParam("EdgeThreshHigh",value);printf("{\"index\":%d,\"dotMode\":%d,\"contrast\":%d,\"low\":%d,\"high\":%d",index++,mode,contrast,high==1?1:20,high);
 try{tool->Run();auto r=tool->GetResult();auto locate=r->GetCalibBoardLocateInfo();auto h=r->GetCalibBoardHomoEstInfo();float matrix[9];h->GetHomoMatrix(matrix);printf(",\"code\":0,\"points\":[");for(int i=0;i<locate->GetCalibPointNum();i++){auto p=locate->GetCalibPointImageCoordinate(i);auto q=locate->GetCalibPointObjectCoordinate(i);printf("%s[%.9g,%.9g,%d,%d]",i?",":"",p.fX,p.fY,q.nX,q.nY);}printf("],\"matrix\":[");for(int i=0;i<9;i++)printf("%s%.9g",i?",":"",matrix[i]);printf("],\"error\":%.9g",h->GetEstimationError());}catch(IMVDException&e){printf(",\"code\":%u",e.GetErrorCode());}printf("}\n");fflush(stdout);destroyImage(image);}
 destroy(tool);return 0;}
